"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { ChevronRight } from "@/components/ui/icons";

// List Item: generated by UIX from the design system. Same variants and sizes as the Figma component.

const listItemVariants = cva(
  "skin-quiet flex w-full items-center gap-3 px-4 py-3 bg-surface",
  {
    variants: {
      type: {
        "one-line": "",
        "two-line": "",
        avatar: "",
        toggle: "",
      },
    },
    defaultVariants: {
      type: "one-line",
    },
  },
);

export interface ListItemProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title">,
    VariantProps<typeof listItemVariants> {
  title: React.ReactNode;
  /** Second line; used by every type except "one-line". */
  subtitle?: React.ReactNode;
  /** Icon or image in the leading box. */
  leading?: React.ReactNode;
  /** Initials for the "avatar" type. */
  initials?: string;
  /** Replaces the trailing chevron. */
  trailing?: React.ReactNode;
  /** State of the switch in the "toggle" type. */
  checked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
  /** Checkbox before the content (for example <Checkbox aria-label="Select" />). */
  leadingCheckbox?: React.ReactNode;
  /** Badge before the chevron or switch (for example a count). */
  trailingBadge?: React.ReactNode;
}

const ListItem = React.forwardRef<HTMLDivElement, ListItemProps>(
  ({ className, type, title, subtitle, leading, initials, trailing, checked = false, onCheckedChange, leadingCheckbox, trailingBadge, ...props }, ref) => {
    const kind = type ?? "one-line";
    return (
      <div data-slot="list-item" data-kind="surface" ref={ref} className={cn(listItemVariants({ type }), className)} {...props}>
        {leadingCheckbox}
        {kind === "avatar" ? (
          <span aria-hidden className="inline-flex shrink-0 items-center justify-center rounded-full size-10 bg-brand-subtle text-label-medium text-fg-brand">
            {initials}
          </span>
        ) : leading ? (
          <span aria-hidden className="inline-flex shrink-0 items-center justify-center size-[36px] rounded-md bg-subtle text-icon-secondary [&_svg]:size-[18px]">
            {leading}
          </span>
        ) : null}
        <div className="flex min-w-0 flex-1 flex-col gap-0-5">
          <span className="text-label-large text-fg-primary">{title}</span>
          {kind !== "one-line" && subtitle ? <span className="text-body-small text-fg-secondary">{subtitle}</span> : null}
        </div>
        {trailingBadge}
        {kind === "toggle" ? (
          <button type="button" role="switch" aria-checked={checked} aria-label={typeof title === "string" ? title : "Toggle"} onClick={() => onCheckedChange?.(!checked)} className="group/switch relative inline-flex shrink-0 cursor-pointer items-center rounded-full transition-colors h-[22px] w-10 bg-muted aria-checked:bg-brand focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus">
            <span aria-hidden className="absolute top-[2px] left-[2px] size-[18px] rounded-full shadow-sm transition-transform group-aria-checked/switch:translate-x-[18px] bg-surface" />
          </button>
        ) : (
          trailing ?? <ChevronRight aria-hidden className="size-5 text-icon-secondary" />
        )}
      </div>
    );
  },
);
ListItem.displayName = "ListItem";

export { ListItem, listItemVariants };
